"use strict";
const bouton = document.querySelector("#ajouter");
const liste = document.querySelector("#taches");
const etat = document.querySelector("#etat");
bouton.addEventListener("click", () => {
  const item = document.createElement("li");
  item.textContent = `Tâche ${liste.children.length + 1}`;
  liste.append(item);
  etat.textContent = `${liste.children.length} tâche(s)`;
});
